# Reference values from OrdinaryDiffEq (OrdinaryDiffEqStabilizedIRK,
# OrdinaryDiffEqBDF), generated by tools/irkc-probe.jl and
# tools/irkc-gen-test.R: steps, evaluations of f1 and f2, Jacobians,
# factorizations, linear solves, rejections and the final state.

irkc_n <- 8
irkc_f1 <- function(u, p, t) {
  l <- c(0, u[-irkc_n]); r <- c(u[-1], 0)
  p[1] * (l - 2 * u + r) * (irkc_n + 1)^2 - 0.5 * (u * u * u)
}
irkc_f2 <- function(u, p, t) p[2] * u * (1 - u) + 0.1 * t
irkc_j1 <- function(u, p, t) {
  J <- matrix(0, irkc_n, irkc_n)
  for (i in seq_len(irkc_n)) {
    J[i, i] <- -2 * p[1] * (irkc_n + 1)^2 - 1.5 * u[i]^2
    if (i > 1) J[i, i - 1] <- p[1] * (irkc_n + 1)^2
    if (i < irkc_n) J[i, i + 1] <- p[1] * (irkc_n + 1)^2
  }
  J
}
irkc_u0 <- seq_len(irkc_n) * (irkc_n + 1 - seq_len(irkc_n)) / irkc_n^2
irkc_cb <- DiscreteCallback(function(u, t, integ) t == 0.1, function(integ) integ$u <- integ$u * 0.5)
irkc_prob <- function(b) {
  SplitODEProblem(SplitFunction(irkc_f1, irkc_f2, jac = irkc_j1), irkc_u0, c(0, 0.3),
                  if (b == 5) c(1, 5) else c(0.2, 40))
}
irkc_solve <- function(case, b, rt) {
  prob <- irkc_prob(b)
  switch(case,
    plain = solve(prob, IRKC(), reltol = rt, abstol = 1e-6),
    tstop = solve(prob, IRKC(), reltol = rt, abstol = 1e-6, tstops = 0.1),
    cb = solve(prob, IRKC(), reltol = rt, abstol = 1e-6, tstops = 0.1, callback = irkc_cb),
    eig = solve(prob, IRKC(eigen_est = 30), reltol = rt, abstol = 1e-6),
    fixed = solve(prob, IRKC(), dt = 1 / 32, adaptive = FALSE))
}
irkc_cases <- list(
  list(alg = "IRKC", a = 5, b = 1e-04, case = "tstop", n = 6L, nf = 560L, nf2 = 267L, njacs = 55L,
       nw = 55L, nsolve = 307L, nreject = 0L, u = c(0.02739875918923166, 0.049686407664005811, 0.066515388536186479, 0.07540208328022753, 0.075402083280227294, 0.066515388536186201, 0.049686407664006192, 0.027398759189231951)),
  list(alg = "IRKC", a = 5, b = 1e-04, case = "fixed", n = 11L, nf = 1056L, nf2 = 527L, njacs = 500L,
       nw = 500L, nsolve = 555L, nreject = 0L, u = c(0.024127889383143083, 0.043265017257031232, 0.057955907780317242, 0.066867694520257911, 0.066867694520257995, 0.057955907780316986, 0.043265017257031385, 0.024127889383142677)),
  list(alg = "IRKC", a = 40, b = 0.001, case = "plain", n = 4L, nf = 537L, nf2 = 172L, njacs = 52L,
       nw = 52L, nsolve = 384L, nreject = 0L, u = c(0.88946149149281295, 1.0739722157741265, 1.0858518944680675, 1.0752274114816851, 1.075227411481674, 1.0858518944680675, 1.0739722157741285, 0.88946149149281339)),
  list(alg = "IRKC", a = 40, b = 0.001, case = "tstop", n = 4L, nf = 494L, nf2 = 169L, njacs = 52L,
       nw = 52L, nsolve = 341L, nreject = 0L, u = c(0.79743825819407954, 1.0129551518224622, 1.0554925235531081, 1.0631293133992017, 1.0631293133992017, 1.0554925235531101, 1.0129551518224622, 0.79743825819407954)),
  list(alg = "IRKC", a = 40, b = 0.001, case = "eig", n = 4L, nf = 537L, nf2 = 151L, njacs = 52L,
       nw = 52L, nsolve = 384L, nreject = 0L, u = c(0.88946149149281295, 1.0739722157741265, 1.0858518944680675, 1.0752274114816851, 1.075227411481674, 1.0858518944680675, 1.0739722157741285, 0.88946149149281339)),
